# Load catalog
catalog = {}
with open(CATALOG_CSV, newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        catalog[row['timeseries_id']] = row

# Find the timeseries ids by point_uri
lighting_ts = None
occupancy_ts = None
for ts_id, info in catalog.items():
    if info['point_uri'] == 'urn:buildgraph:tsref:a3d53062-bb91-5344-944b-d0a1d130ccbd':
        lighting_ts = ts_id
    if info['point_uri'] == 'urn:buildgraph:tsref:ff8945c5-3435-5fa7-bdc7-9f8f355a8c99':
        occupancy_ts = ts_id

print(f"Lighting TS: {lighting_ts}")
print(f"Occupancy TS: {occupancy_ts}")

# Load values for those two TS on 2018-01-17
lighting_vals = {}
occupancy_vals = {}
with open(VALUES_CSV, newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ts = row['timeseries_id']
        if ts == lighting_ts or ts == occupancy_ts:
            if row['timestamp'].startswith('2018-01-17'):
                val = float(row['value'])
